// Characterization tests: pin CURRENT behaviour of the HTTP API. Contract: test/orders.openapi.yaml
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// In-process fake of the downstream pricing service (priceOf(sku) -> euros)
const prices = { A: 10, B: 25.5, C: 60 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const call = async (method, path, body, raw) => {
  const res = await fetch(base + path, { method, body: raw ?? (body === undefined ? undefined : JSON.stringify(body)) })
  return { status: res.status, type: res.headers.get('content-type'), json: await res.json() }
}

// Order matters: ids come from a module-level counter shared across the process.
test('POST /orders 201 creates order, no discount at or below 100', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }] })
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.json, { id: '1', items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }], total: 45 }) // 45.5 floored
})

test('POST /orders applies 10% discount strictly above 100', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'C', qty: 2 }] }) // 120 -> 108
  assert.equal(r.status, 201)
  assert.equal(r.json.id, '2')
  assert.equal(r.json.total, 108)
})

test('POST /orders exactly 100 is not discounted', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'A', qty: 10 }] })
  assert.equal(r.json.total, 100)
})

test('POST /orders total is floored after discount', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'B', qty: 5 }] }) // 127.5 -> 114.75
  assert.equal(r.json.total, 114)
})

test('POST /orders unknown sku yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — undefined price gives NaN, serialized as null, still 201
  const r = await call('POST', '/orders', { items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(r.status, 201)
  assert.equal(r.json.total, null)
})

test('POST /orders missing qty yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation (NaN -> null)
  const r = await call('POST', '/orders', { items: [{ sku: 'A' }] })
  assert.equal(r.status, 201)
  assert.equal(r.json.total, null)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'x' }],
  ['empty body', undefined],
  ['invalid JSON', undefined, '{nope'],
  ['JSON null', undefined, 'null'],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const r = await call('POST', '/orders', body, raw)
    assert.equal(r.status, 400)
    assert.deepEqual(r.json, { error: 'items required' })
  })
}

test('GET /orders/:id returns a stored order', async () => {
  const r = await call('GET', '/orders/2')
  assert.equal(r.status, 200)
  assert.deepEqual(r.json, { id: '2', items: [{ sku: 'C', qty: 2 }], total: 108 })
})

test('GET /orders/:id unknown id returns 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const r = await call('GET', '/orders/999')
  assert.equal(r.status, 200)
  assert.deepEqual(r.json, { error: 'not found' })
})

test('404 no route for unknown path, wrong method, nested path', async () => {
  for (const [m, p] of [['GET', '/nope'], ['GET', '/orders'], ['POST', '/orders/1'], ['DELETE', '/orders/1'], ['GET', '/orders/1/x']]) {
    const r = await call(m, p)
    assert.equal(r.status, 404, `${m} ${p}`)
    assert.deepEqual(r.json, { error: 'no route' })
  }
})
